var DATA = {"model": "y = a*exp(-b*t)", "params": "a|b", "result": "Structurally identifiable", "method": "Differential algebra", "corr": "0.1|0.1"};
console.log("Model: " + DATA.model + " | Method: " + DATA.method);
var params = DATA.params.split("|").map(function (s) { return s.trim(); });
var corrs = DATA.corr.split("|").map(function (s) { return parseFloat(s); });
// profile-likelihood sketch: for each parameter, scan values and compute a fake
// negative log-likelihood with a valley; flat valley => not identifiable
params.forEach(function (p, i) {
  var c = corrs[i % corrs.length];
  var valley = [];
  for (var v = -2; v <= 2; v += 1) {
    // curvature shrinks as |correlation| grows: flat => unidentifiable
    var nll = (1 - Math.min(0.95, Math.abs(c))) * v * v;
    valley.push(nll.toFixed(2));
  }
  var flat = Math.abs(c) > 0.9;
  console.log("  " + p + ": profile [" + valley.join(", ") + "] corr=" + c + " => " + (flat ? "NOT identifiable (flat)" : "identifiable"));
});
console.log("Result: " + DATA.result);
console.log("RESULT: identifiability profiled for " + params.length + " parameters.");

